const AdmZip = require('/tmp/nodelibs/node_modules/adm-zip');
const zip = new AdmZip('/workspace/testbed/docs/customer_report.docx');
const xml = zip.getEntry('word/document.xml').getData().toString('utf-8');

// Extract paragraph-by-paragraph for proper formatting
const pRegex = /<w:p[ >][\s\S]*?<\/w:p>/g;
let para;
while ((para = pRegex.exec(xml)) !== null) {
  const tMatches = para[0].match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
  const text = tMatches.map(m => m.replace(/<[^>]+>/g, '')).join('');
  if (text.trim()) console.log(text);
}
"

